--
-- Name: fn_dept_headcount_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_dept_headcount_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE departments
    SET headcount = (
        SELECT COUNT(*)
        FROM   employees
        WHERE  department_id = COALESCE(NEW.department_id, OLD.department_id)
          AND  status = 'active'
    )
    WHERE id = COALESCE(NEW.department_id, OLD.department_id);
    RETURN NEW;
END;
$$;


--
-- Name: fn_stock_touch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_stock_touch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.last_updated := NOW();
    RETURN NEW;
END;
$$;


